import React, { useState } from 'react'
import './components/VistaFormularioRegistro.css'
const VistaFormularioRegistro = ({ onVolver }) => {
  // Estados para cada campo
  const [fecha, setFecha] = useState('')
  const [hora, setHora] = useState('')
  const [magnitud, setMagnitud] = useState('')
  const [latitud, setLatitud] = useState('')
  const [longitud, setLongitud] = useState('')
  const [profundidad, setProfundidad] = useState('')
  const [referencia, setReferencia] = useState('')
  const [estatus, setEstatus] = useState('')

  // Para mostrar la respuesta o el error
  const [responseData, setResponseData] = useState(null)
  const [errorMsg, setErrorMsg] = useState(null)
  const [isSubmitting, setIsSubmitting] = useState(false)

  const handleSubmit = async e => {
    e.preventDefault()
    setErrorMsg(null)
    setResponseData(null)
    setIsSubmitting(true)

    // Construir payload
    const payload = {
      fecha,
      hora,
      magnitud: Number(magnitud),
      latitud: Number(latitud),
      longitud: Number(longitud),
      profundidad: Number(profundidad),
      referenciaLocalizacion: referencia,
      estatus
    }

    try {
      const resp = await fetch(
        'http://localhost:8080/inicio/registroSismo',
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            accept: 'application/json'
          },
          body: JSON.stringify(payload)
        }
      )
      if (!resp.ok) {
        const text = await resp.text()
        throw new Error(
          `Error ${resp.status}: ${text || resp.statusText}`
        )
      }
      const data = await resp.json()
      setResponseData(data)
    } catch (err) {
      setErrorMsg(err.message)
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="vf-container">
      <div className="vf-card">
        <div className="vf-header">
          {/* Icono SVG */}
          <svg
            className="vf-header-icon"
            viewBox="0 0 24 24"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              fill="white"
              d="M4 12l3-8 4 16 3-12 3 8 4-4"
            />
          </svg>
          <h2 className="vf-header-title">
            Registro de Evento Sísmico
          </h2>
        </div>

        <form onSubmit={handleSubmit} className="vf-form">
          <div className="vf-form-group">
            <label>Fecha</label>
            <input
              type="date"
              value={fecha}
              onChange={e => setFecha(e.target.value)}
              required
            />
          </div>

          <div className="vf-form-group">
            <label>Hora</label>
            <input
              type="time"
              value={hora}
              onChange={e => setHora(e.target.value)}
              required
            />
          </div>

          <div className="vf-form-group">
            <label>Magnitud</label>
            <input
              type="number"
              step="0.1"
              min="0"
              value={magnitud}
              onChange={e => setMagnitud(e.target.value)}
              placeholder="p.ej. 4.5"
              required
            />
          </div>

          <div className="vf-form-group">
            <label>Latitud</label>
            <input
              type="number"
              step="0.0001"
              value={latitud}
              onChange={e => setLatitud(e.target.value)}
              placeholder="p.ej. 19.4326"
              required
            />
          </div>

          <div className="vf-form-group">
            <label>Longitud</label>
            <input
              type="number"
              step="0.0001"
              value={longitud}
              onChange={e => setLongitud(e.target.value)}
              placeholder="p.ej. -99.1332"
              required
            />
          </div>

          <div className="vf-form-group">
            <label>Profundidad (km)</label>
            <input
              type="number"
              step="0.1"
              min="0"
              value={profundidad}
              onChange={e => setProfundidad(e.target.value)}
              placeholder="p.ej. 10"
              required
            />
          </div>

          <div className="vf-form-group">
            <label>Referencia de Localización</label>
            <input
              type="text"
              value={referencia}
              onChange={e => setReferencia(e.target.value)}
              placeholder="p.ej. 5 km al SE de X"
              required
            />
          </div>

          <div className="vf-form-group">
            <label>Estatus</label>
            <select
              value={estatus}
              onChange={e => setEstatus(e.target.value)}
              required
            >
              <option value="">-- Selecciona --</option>
              <option value="CONFIRMADO">CONFIRMADO</option>
              <option value="PENDIENTE">PENDIENTE</option>
              <option value="REVISAR">REVISAR</option>
            </select>
          </div>

          <div className="vf-buttons">
            <button
              type="submit"
              className="vf-btn vf-btn-primary"
              disabled={isSubmitting}
            >
              {isSubmitting ? 'Enviando...' : 'Guardar'}
            </button>
            <button
              type="button"
              className="vf-btn vf-btn-secondary"
              onClick={onVolver}
              disabled={isSubmitting}
            >
              Volver
            </button>
          </div>
        </form>

        {/* Mensajes de éxito o error */}
        {responseData && (
          <div className="vf-response vf-success">
            <h4>Registro exitoso:</h4>
            <pre>{JSON.stringify(responseData, null, 2)}</pre>
          </div>
        )}
        {errorMsg && (
          <div className="vf-response vf-error">
            <h4>Ocurrió un error:</h4>
            <p>{errorMsg}</p>
          </div>
        )}
      </div>
    </div>
  )
}

export default VistaFormularioRegistro
